import os
import hmac
import hashlib
import sqlite3
import json
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')
HMAC_SECRET = os.environ.get('HMAC_SECRET', 'changeme-in-production')
ADMIN_TOKEN = os.environ.get('ADMIN_TOKEN', 'supersecretadmintoken')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner TEXT NOT NULL,
        title TEXT NOT NULL,
        content TEXT,
        classification TEXT DEFAULT 'internal',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        key_hash TEXT NOT NULL,
        owner TEXT NOT NULL,
        scope TEXT DEFAULT 'read',
        revoked INTEGER DEFAULT 0
    )''')
    db.execute("INSERT OR IGNORE INTO documents (id, owner, title, content, classification) VALUES (1, 'admin', 'Secret Strategy', 'Acquisition target: CompanyX at $4.2B', 'top-secret')")
    db.execute("INSERT OR IGNORE INTO documents (id, owner, title, content, classification) VALUES (2, 'admin', 'Board Minutes', 'CEO compensation: $12M + equity', 'confidential')")
    db.execute("INSERT OR IGNORE INTO documents (id, owner, title, content, classification) VALUES (3, 'jsmith', 'Project Plan', 'Q4 deliverables overview', 'internal')")
    db.commit()
    db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    if not key:
        return None, None
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    db = get_db()
    row = db.execute('SELECT owner, scope FROM api_keys WHERE key_hash = ? AND revoked = 0', (key_hash,)).fetchone()
    if row:
        return row['owner'], row['scope']
    return None, None

@app.route('/api/documents/search', methods=['GET'])
def search_documents():
    owner, scope = verify_api_key(request)
    if not owner:
        return jsonify({'error': 'unauthorized'}), 401

    query = request.args.get('q', '')
    classification = request.args.get('classification', 'internal')
    sort_by = request.args.get('sort', 'created_at')

    # Build query with parameterized owner filter
    sql = f"SELECT id, title, classification, created_at FROM documents WHERE owner = ? AND classification = '{classification}'"

    if query:
        sql += f" AND (title LIKE '%{query}%' OR content LIKE '%{query}%')"

    sql += f" ORDER BY {sort_by}"

    try:
        results = get_db().execute(sql, (owner,)).fetchall()
        return jsonify({'documents': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    owner, scope = verify_api_key(request)
    if not owner:
        return jsonify({'error': 'unauthorized'}), 401
    row = get_db().execute('SELECT * FROM documents WHERE id = ? AND owner = ?', (doc_id, owner)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'db': DB_PATH, 'version': '2.3.1'})

@app.route('/api/admin/keys', methods=['POST'])
def create_api_key():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    if not hmac.compare_digest(token, ADMIN_TOKEN):
        return jsonify({'error': 'forbidden'}), 403
    data = request.get_json()
    raw_key = os.urandom(24).hex()
    key_hash = hashlib.sha256(raw_key.encode()).hexdigest()
    db = get_db()
    db.execute('INSERT INTO api_keys (key_hash, owner, scope) VALUES (?, ?, ?)',
               (key_hash, data['owner'], data.get('scope', 'read')))
    db.commit()
    return jsonify({'key': raw_key, 'owner': data['owner']})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
